{
  "sample_size": 130,
  "alpha": 0.05,
  "sided": 2,
  "power": 0.85,
  "effect_size": 0.24,
  "effect_type": "proportions",
  "control_rate": 0.10,
  "dropout": 0.10,
  "analyses": [
    {
      "endpoint_ids": ["ep_1"],
      "method": "Chi-square test",
      "quote": "This sample size will yield >85% power to detect a treatment difference of 24% in the proportion of patients achieving IGA hand and foot (0, 1) at week 16 between placebo (10%) and dupilumab (34%) at a 2-sided significant level of 5% using Chi-square test and assuming a dropout rate of 10%."
    },
    {
      "endpoint_ids": ["ep_1"],
      "method": "Cochran-Mantel-Haenszel (CMH) test",
      "quote": "The primary endpoint of proportion of patients achieving an IGA score of 0 or 1 on hand and foot at week 16 will be analyzed using the Cochran-Mantel-Haenszel (CMH) test to assess the difference in the proportion of responders in the FAS adjusting for the randomization stratification factors (age [adults vs. adolescents], disease severity of IGA hand and foot [3 vs. 4], and geographic region [United States versus Japan versus other countries])."
    },
    {
      "endpoint_ids": ["ep_1"],
      "method": "Sensitivity analysis using LOCF or WOCF",
      "quote": "Sensitivity analysis using the last observation carried forward (LOCF) approach or the worst observation carried forward (WOCF) approach to determine patient’s status at week 16 will be conducted to assess the robustness of the primary efficacy analysis with regards to handling of missing data."
    },
    {
      "endpoint_ids": ["ep_1"],
      "method": "CMH method adjusted by randomization strata on all observed data",
      "quote": "In addition, the CMH method adjusted by randomization strata will also be performed on all observed data regardless if rescue treatment is used."
    },
    {
      "endpoint_ids": ["ep_2"],
      "method": "Same as primary analysis (CMH test)",
      "quote": "Secondary efficacy endpoints that measure binary responses (eg, improvement of weekly average of daily peak Pruritus NRS ≥4 from baseline to week 16) will be analyzed in the same fashion as the primary analysis."
    },
    {
      "endpoint_ids": ["ep_5"],
      "method": "ANCOVA model",
      "quote": "Continuous secondary efficacy endpoints (eg, percent change mTLSS for hand/foot lesions from baseline to week 16) will be analyzed using an analysis of covariance (ANCOVA) model for the FAS with treatment group, randomization stratification factors (age [adults vs. adolescents], disease severity of IGA hand and foot [3 vs. 4], and geographic region [United States versus Japan versus other countries]), and relevant baseline measurement included in the model."
    },
    {
      "endpoint_ids": ["ep_5"],
      "method": "Empirical cumulative distribution function (CDF) curves",
      "quote": "For the endpoint of percent change in mTLSS for hand/foot lesions from baseline to week 16, the empirical cumulative distribution function (CDF) curves showing response in dupilumab and placebo groups for different responder thresholds will be provided."
    }
  ]
}
